/* true60 (the whole-frame form rule addendum): the Morth whole form. The frame decides from Link (the
 * search, the stick-on, Link's heavy counter) and the tick30 collision, and its eases, timers, RNG draws and morf play
 * run once per 30 Hz frame; as per-step forms its eases left it off A's frame with cLib run for real (N-step spec daKS_Execute
 * 8827/10000). So daKS_Execute runs whole once per 30 Hz frame on the tick30 step at dt 1 from the frame-start state
 * (d/t60_whole.h, t60objw form); the earlier steps change no logic state; the picture (also the pose stuck on Link,
 * from Link's joint matrix): frame interpolation / the process-order read rule. The per-step helpers below are inert inside the whole run (dt 1). */
struct ks_class;
namespace ks_t60w {
static inline const t60w::Ops<ks_class>& ops() { return t60objw::Logic<ks_class>::kOps; }
}  // namespace ks_t60w
#include "d/t60conv.h"

/* true60 (the per-step movement rule,'s exact arc for inline gravity): the y offset dv x (1 - dt) / 2 for this step's gravity change dv
 * (after the -20 clamp), so N steps of (v += g dt; p += v dt + arc) end where the original (v += g; p += v) ends */
static inline f32 ks_t60_arc(f32 dv) {
#ifdef T60C_NEGCTRL
    (void)dv;
    return 0.0f;
#else
    if (!t60c::on())
        return 0.0f;
    return gabi::fmuls_ppc(gabi::fmuls_ppc(dv, gabi::fsubs_ppc(1.0f, t60::dt())), 0.5f);
#endif
}


/* true60 (2026-11-18, picture only): the spins, the tumble and the stuck turn are added once per 30 Hz frame on the
 * first step (shape_angle feeds the hop / landing logic, so the stored value keeps the original per-frame form). The
 * picture draws them with a per-step share instead: draw_SUB runs on a local copy that lags the stored value by the part
 * of the frame's add the frame's later steps have not reached ((N - 1 - j) / N of it on step j; none on the tick30 step,
 * none at dt 1), and the stored values are put back after the draw (never written back). Host table entries only. */
enum { KS_T60_PIC_STEP = 20, KS_T60_PIC_Z = 21, KS_T60_PIC_Y = 22 };
static inline s32& ks_t60_pic_entry(const void* k, int site) {
    const u32 tag = t60c::frameTag();
    t60c::AddEntry& e = t60c::s_add.at(t60c::key(k, site) ^ 0x1000000000000000ull, tag);
    if (e.tag != tag) {
        e.tag = tag;
        e.given = 0;
    }
    return e.given;
}
/* counts the execute steps of this frame (call once per execute, before any add) */
static inline void ks_t60_pic_begin(const void* k) {
#ifndef T60C_NEGCTRL
    if (t60c::on())
        ks_t60_pic_entry(k, KS_T60_PIC_STEP) += 1;
#else
    (void)k;
#endif
}
/* a first-step add of `add` to the angle (site Z or Y), for the picture share */
static inline void ks_t60_pic_add(const void* k, int site, s32 add) {
#ifndef T60C_NEGCTRL
    if (t60c::on())
        ks_t60_pic_entry(k, site) += add;
#else
    (void)k, (void)site, (void)add;
#endif
}
/* the part of a per-frame amount the picture has not reached on this step */
static inline s16 ks_t60_pic_lag(const void* k, s32 perFrame) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || t60::tick30() || perFrame == 0)
        return 0;
    const s32 n = (s32)t60::steps();
    const s32 j = ks_t60_pic_entry(k, KS_T60_PIC_STEP);  /* 1 on the first step */
    if (n <= 1 || j <= 0 || j >= n)
        return 0;
    return (s16)(((long long)perFrame * (n - j)) / n);
#else
    (void)k, (void)perFrame;
    return 0;
#endif
}
static inline s32 ks_t60_pic_sum(const void* k, int site) {
#ifndef T60C_NEGCTRL
    return t60c::on() ? ks_t60_pic_entry(k, site) : 0;
#else
    (void)k, (void)site;
    return 0;
#endif
}

/* the arc offset as a speed for posMove's step (p += v dt): arc / dt; 0 at dt 1 */
static inline f32 ks_t60_arc_speed(f32 arc) {
    return t60c::on() ? arc / t60::dt() : 0.0f;
}

/* true60 (ks case 2): a decision on another actor's state (Link's `speedF > 12`) is taken on the
 * frame's tick30 step from the live (= frame-end, Link runs before the Morth) value, as A's Morth reads Link's frame-end
 * value; the frame's earlier steps keep the answer the previous frame's tick30 step took (order beats first-step
 * placement, first-step AI-timer), so the run starts with the tick30 step's share. Host table: the tick30 step stores the answer under
 * the frame tag, an earlier step of the next frame takes it over (re-tagged to keep the slot); no stored answer (the
 * first frame, a lost slot, a frame gap) falls back to the live value. dt 1: the live value (the original). */
enum { KS_T60_LINKFAST = 23 };
static inline bool ks_t60_link_decision(const void* k, bool live) {
#ifdef T60C_NEGCTRL
    (void)k;
    return live;
#else
    if (!t60c::on())
        return live;
    const u32 tag = t60c::frameTag();
    /* the answer is stored with the actor's process id (base +0x04): a new actor at a freed address (or the harness's
     * next generated input) does not take over a stale answer */
    const u32 pcid = gabi::load<u32>(gabi::ea(k) + 4) & 0x7FFFFFFFu; /* base_process_class::mBsPcId */
    t60c::AddEntry& e = t60c::s_held.at(t60c::key(k, KS_T60_LINKFAST) ^ 0x2000000000000000ull, tag);
    if (t60::tick30()) {
        e.tag = tag;
        e.given = (s32)((pcid << 1) | (live ? 1u : 0u));
        return live;
    }
    if ((e.tag == tag || e.tag == tag - 1u) && (((u32)e.given >> 1) == pcid)) {
        e.tag = tag;
        return (e.given & 1) != 0;
    }
    return live;
#endif
}

/* true60 (the first-step AI-timer catch-up addendum): a motion or launch case 2 decides on the tick30 step (the
 * run / damp branch switched from the frame's earlier steps' branch on Link's frame-end speed, the attack, the run's hop)
 * catches up the frame's earlier steps, so the frame ends where A's does: A decided before moving within the frame, so
 * its started motion moves the whole frame's amount. The tick30 step goes back to the frame-start position (x / z; y for
 * a hop launched there) and moves the whole frame's amount (speed / dt for its posMove, the sway shift x 1).
 * Host table: the frame-start position latched on the first step (float bits, s_add sites 24-26). dt 1: nothing. */
enum { KS_T60_POS_X = 24, KS_T60_POS_Y = 25, KS_T60_POS_Z = 26 };
enum { KS_T60_G0 = 8, KS_T60_CATCH = 9, KS_T60_CATCH_HOP = 10 };
static inline s32 ks_t60_fbits(f32 v) { union { f32 f; s32 i; } u; u.f = v; return u.i; }
static inline f32 ks_t60_bitsf(s32 v) { union { f32 f; s32 i; } u; u.i = v; return u.f; }
static inline t60c::AddEntry& ks_t60_pos_entry(const void* k, int site) {
    return t60c::s_add.at(t60c::key(k, site) ^ 0x0800000000000000ull, t60c::frameTag());
}
/* call once per execute on every step, before the dispatch */
static inline void ks_t60_pos_begin(const void* k, const cXyz& pos) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || !t60::first_step())
        return;
    const u32 tag = t60c::frameTag();
    t60c::AddEntry* e[3] = {&ks_t60_pos_entry(k, KS_T60_POS_X), &ks_t60_pos_entry(k, KS_T60_POS_Y),
                            &ks_t60_pos_entry(k, KS_T60_POS_Z)};
    e[0]->given = ks_t60_fbits(pos.x);
    e[1]->given = ks_t60_fbits(pos.y);
    e[2]->given = ks_t60_fbits(pos.z);
    e[0]->tag = e[1]->tag = e[2]->tag = tag;
#else
    (void)k, (void)pos;
#endif
}
/* the frame-start coordinate (site X / Y / Z); false: none latched this frame (keep the per-step form) */
static inline bool ks_t60_pos_start(const void* k, int site, f32* out) {
#ifndef T60C_NEGCTRL
    t60c::AddEntry& e = ks_t60_pos_entry(k, site);
    if (e.tag != t60c::frameTag())
        return false;
    *out = ks_t60_bitsf(e.given);
    return true;
#else
    (void)k, (void)site, (void)out;
    return false;
#endif
}
/* true60 (the first-step push rule; on pair, the Co push as a process-order read addendum case): what the
 * collision system writes into a Morth within a frame takes effect from the next frame's first step, once. In A dCcS
 * resolves Co after the frame's executes (m_cc_move = the frame-end overlap) and the execute moves by it on the next
 * frame. At N > 1 dCcS::Move runs after every step and lists the converted colliders (Morths, Link) on the in-between
 * steps too, so an in-between Move rewrote m_cc_move from the step's half-frame positions and the tick30 step moved by
 * that push a frame early (f203), then every step by its own step's push. Form: the push the frame's first step sees
 * (the last tick30 Move's, A's) is latched (float bits, s_add sites 27-29) and given to every posMove of the frame
 * (fopAcM_posMove takes dt of it: the frame's total is A's push); an in-between Move's value is never consumed; no
 * latch this frame (created on a later step): no push, as A's first execute. The tick30 catch-up (whole frame's move
 * from the frame-start position) takes the whole push (x 1 / dt on the axes it put back). dt 1: nothing. */
enum { KS_T60_CC_X = 27, KS_T60_CC_Y = 28, KS_T60_CC_Z = 29 };
/* call once per execute on every step, before the dispatch (with ks_t60_pos_begin) */
template <class V> static inline void ks_t60_cc_begin(const void* k, const V& cc) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || !t60::first_step())
        return;
    const u32 tag = t60c::frameTag();
    t60c::AddEntry* e[3] = {&ks_t60_pos_entry(k, KS_T60_CC_X), &ks_t60_pos_entry(k, KS_T60_CC_Y),
                            &ks_t60_pos_entry(k, KS_T60_CC_Z)};
    e[0]->given = ks_t60_fbits((f32)cc.x);
    e[1]->given = ks_t60_fbits((f32)cc.y);
    e[2]->given = ks_t60_fbits((f32)cc.z);
    e[0]->tag = e[1]->tag = e[2]->tag = tag;
#else
    (void)k, (void)cc;
#endif
}
/* before the posMove that consumes m_cc_move: the frame's push in place of the step's Move value */
template <class V> static inline void ks_t60_cc_step(const void* k, V* cc, bool catchXZ, bool catchY) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    f32 x = 0.0f, y = 0.0f, z = 0.0f;
    if (ks_t60_pos_start(k, KS_T60_CC_X, &x) && ks_t60_pos_start(k, KS_T60_CC_Y, &y) &&
        ks_t60_pos_start(k, KS_T60_CC_Z, &z)) {
        const f32 inv = 1.0f / t60::dt();
        if (catchXZ) {
            x = gabi::fmuls_ppc(x, inv);
            z = gabi::fmuls_ppc(z, inv);
        }
        if (catchY) y = gabi::fmuls_ppc(y, inv);
    } else {
        x = y = z = 0.0f;
    }
    cc->x = x;
    cc->y = y;
    cc->z = z;
#else
    (void)k, (void)cc, (void)catchXZ, (void)catchY;
#endif
}
/* the sphere centre for the tick30 collision Move: A's Move checks the sphere set before the frame's posMove, i.e. the
 * frame-start position plus what the frame's dispatch moved it directly (sway shift ...), without the frame's posMove.
 * B on the tick30 step: the live position minus the earlier steps' posMove displacements (accumulated per frame, float
 * bits in s_add sites 30-32, reset on the first step; ks_t60_mv_begin / ks_t60_mv_end around the posMove). A catch-up
 * step put the frame-start position back itself: live. true: written to *out; dt 1 / an earlier step: false (live). */
enum { KS_T60_MV_X = 30, KS_T60_MV_Y = 31, KS_T60_MV_Z = 32 };
static inline f32 ks_t60_mv_get(const void* k, int site) {
    t60c::AddEntry& e = ks_t60_pos_entry(k, site);
    return e.tag == t60c::frameTag() ? ks_t60_bitsf(e.given) : 0.0f;
}
static inline void ks_t60_mv_set(const void* k, int site, f32 v) {
    t60c::AddEntry& e = ks_t60_pos_entry(k, site);
    e.given = ks_t60_fbits(v);
    e.tag = t60c::frameTag();
}
template <class V> static inline bool ks_t60_cc_at(const void* k, V* out, const cXyz& live) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || !t60::tick30() || t60c::marked(KS_T60_CATCH, k))
        return false;
    out->x = gabi::fsubs_ppc(live.x, ks_t60_mv_get(k, KS_T60_MV_X));
    out->y = gabi::fsubs_ppc(live.y, ks_t60_mv_get(k, KS_T60_MV_Y));
    out->z = gabi::fsubs_ppc(live.z, ks_t60_mv_get(k, KS_T60_MV_Z));
    return true;
#else
    (void)k, (void)out, (void)live;
    return false;
#endif
}
/* around the step's posMove (earlier steps only matter): the step's displacement added to the frame's sum */
static inline void ks_t60_mv_begin(const void* k) {
#ifndef T60C_NEGCTRL
    if (t60c::on() && t60::first_step()) {
        ks_t60_mv_set(k, KS_T60_MV_X, 0.0f);
        ks_t60_mv_set(k, KS_T60_MV_Y, 0.0f);
        ks_t60_mv_set(k, KS_T60_MV_Z, 0.0f);
    }
#else
    (void)k;
#endif
}
static inline void ks_t60_mv_end(const void* k, f32 x0, f32 y0, f32 z0, const cXyz& pos) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || t60::tick30())
        return;
    ks_t60_mv_set(k, KS_T60_MV_X, ks_t60_mv_get(k, KS_T60_MV_X) + (pos.x - x0));
    ks_t60_mv_set(k, KS_T60_MV_Y, ks_t60_mv_get(k, KS_T60_MV_Y) + (pos.y - y0));
    ks_t60_mv_set(k, KS_T60_MV_Z, ks_t60_mv_get(k, KS_T60_MV_Z) + (pos.z - z0));
#else
    (void)k, (void)x0, (void)y0, (void)z0, (void)pos;
#endif
}
/* the tick30 step's catch-up: back to the frame-start x / z (and y with `y`); marks the posMove scaling */
static inline void ks_t60_catch_begin(const void* k, cXyz* pos, bool y) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || !t60::tick30())
        return;
    f32 x0, y0, z0;
    if (!ks_t60_pos_start(k, KS_T60_POS_X, &x0) || !ks_t60_pos_start(k, KS_T60_POS_Y, &y0) ||
        !ks_t60_pos_start(k, KS_T60_POS_Z, &z0))
        return;
    pos->x = x0;
    pos->z = z0;
    t60c::mark(KS_T60_CATCH, k);
    if (y) {
        pos->y = y0;
        t60c::mark(KS_T60_CATCH_HOP, k);
    }
#else
    (void)k, (void)pos, (void)y;
#endif
}
/* a decision case 2 takes on the tick30 step that the frame's earlier steps did not take (they ran the damp branch on
 * the held Link answer), on the frame-start ground answer (A's tyaku_check reads the previous frame's BG check) */
static inline bool ks_t60_c2_late(const void* k, int dampSite) {
#ifndef T60C_NEGCTRL
    return t60c::on() && t60::tick30() && t60c::marked(dampSite, k);
#else
    (void)k, (void)dampSite;
    return false;
#endif
}
